def compare_variables(var1, var2):
    """
    Compares two variables and returns the result as a string.

    :param var1: The first variable to compare.
    :param var2: The second variable to compare.
    :return: A string indicating whether var1 is less than, equal to, or greater than var2.
    """
    if var1 < var2:
        return str(var1) + " is less than " + str(var2)
    elif var1 == var2:
        return str(var1) + " is equal to " + str(var2)
    else:
        return str(var1) + " is greater than " + str(var2)

# Example usage:
var1 = 10
var2 = 20
print(compare_variables(var1, var2))  # Output: 10 is less than 20
```

